// One item per Data Table row id that went into the brief, for the update node.
const ids = ($('Collect').first().json.briefed_ids || [])
  .filter((x) => x !== null && x !== undefined);
return ids.map((id) => ({ json: { row_id: id } }));

// One item per article.
// Row data comes from Get row(s) via pairedItem; fetched page HTML is on $json.data.
const row = $('Get row(s)').item.json;
const resp = $json || {};

const MAX_CHARS = 7000;   // per-article context budget

// Pull the ARTICLE BODY out of the page, not the whole DOM.
// The old version stripped tags off everything, so the model was fed nav menus,
// language pickers and version archives instead of the article.
function extract(html) {
  let h = String(html || '');
  h = h.replace(/<!--[\s\S]*?-->/g, ' ');
  h = h.replace(/<(script|style|noscript|svg|form|iframe|template)\b[\s\S]*?<\/\1>/gi, ' ');
  h = h.replace(/<(nav|header|footer|aside)\b[\s\S]*?<\/\1>/gi, ' ');

  let m = h.match(/<(article|main)\b[^>]*>([\s\S]*?)<\/\1>/i);
  if (m) {
    h = m[2];
  } else {
    m = h.match(/<div[^>]+(?:role=["']main["']|class=["'][^"']*(?:post-content|entry-content|article-body|article__body|markdown-body|prose)[^"']*["'])[^>]*>([\s\S]*?)<\/div>/i);
    if (m) h = m[1];
  }

  h = h.replace(/<(p|br|h[1-6]|li|div|tr|blockquote|pre)\b[^>]*>/gi, '\n');
  h = h.replace(/<[^>]+>/g, ' ');
  h = h.replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&quot;/gi, '"')
       .replace(/&#0?39;|&apos;/gi, "'").replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
       .replace(/&[a-z#0-9]+;/gi, ' ');

  const lines = h.split('\n')
    .map((l) => l.replace(/[ \t]+/g, ' ').trim())
    .filter((l) => l.length > 40);
  return lines.join('\n').replace(/\n{2,}/g, '\n').trim();
}

// Length alone is not enough: JS-shell and nav-only pages still yield hundreds of
// chars of fragments. Real prose has sentences and long lines.
function looksLikeProse(t) {
  if (!t || t.length < 600) return false;
  const sentences = (t.match(/[.!?]["')\]]?(\s|$)/g) || []).length;
  const longLines = t.split('\n').filter((l) => l.length > 80).length;
  return sentences >= 6 && longLines >= 3;
}

let text = '';
let source = 'article';

if (resp && resp.data && !resp.error) text = extract(resp.data).slice(0, MAX_CHARS);

// Tier 2: page unusable (JS shell, SPA, paywall, 404) -> SearXNG.
// NOTE: as of 2026-09-13 the SearXNG instance returns 0 results for every query
// (brave/duckduckgo/startpage/wikidata all CAPTCHA'd or suspended). This tier is
// kept because it is correct once SearXNG is healthy; it degrades to tier 3 today.
if (!looksLikeProse(text)) {
  try {
    const sx = await this.helpers.httpRequest({
      method: 'GET',
      url: 'http://searxng.searxng.svc.cluster.local:8080/search',
      qs: { q: String(row.title || '').slice(0, 220), format: 'json', language: 'en' },
      json: true,
      timeout: 15000,
    });
    const hits = ((sx && sx.results) || []).slice(0, 6)
      .map((r) => `${r.title}\n${r.url}\n${String(r.content || '').trim()}`)
      .filter((s) => s.length > 60);
    if (hits.length) {
      text = hits.join('\n\n').slice(0, MAX_CHARS);
      source = 'general web search';
    }
  } catch (e) {
    // fall through to tier 3
  }
}

// Tier 3: nothing retrievable. Do NOT invent an article summary - describe what the
// curator already asserted, clearly labelled, so the entry is still useful.
if (source === 'article' && !looksLikeProse(text)) {
  source = 'curator note only';
  text = '';
}

let SYS;
if (source === 'curator note only') {
  SYS = [
    'You are writing ONE entry of a daily briefing for an experienced infrastructure and platform engineer.',
    'The article page could NOT be retrieved (JS-only page, paywall, or anti-bot), and web search is unavailable.',
    'You have ONLY the title, URL and the curator note explaining why it was flagged.',
    '',
    'Do NOT invent the article contents, findings, numbers or claims.',
    '',
    'Output EXACTLY these three lines and nothing else:',
    'Topic: <the subject, inferred from the title only>',
    'Source: curator note only',
    'Summary: <ONE short paragraph, max 3 sentences. State plainly that the page could not be retrieved, then relay what the curator note says this is about and why it was flagged. No speculation about the contents.>',
  ].join('\n');
} else {
  SYS = [
    'You are a precise technical research assistant writing ONE entry of a daily briefing for an experienced infrastructure and platform engineer.',
    '',
    'You receive one article: its title, URL, an optional curator note, and text captured from the page (it may be truncated mid-sentence).',
    '',
    'Rules:',
    '- Summarise ONLY from the supplied text. Never invent details, numbers, versions or claims.',
    '- Keep the specifics an engineer would act on: version numbers, API and field names, benchmark figures, architectural choices, tradeoffs, limitations.',
    '- Write for someone deciding from your summary whether to read the original.',
    '- If the supplied text turns out to be navigation or boilerplate rather than the article, set Summary to exactly: (page content not retrievable)',
    '',
    'Output EXACTLY these three lines and nothing else:',
    'Topic: <one specific line naming the actual subject, not the title reworded>',
    'Source: ' + source,
    'Summary: <2 to 3 paragraphs of plain prose. Lead with the concrete change, finding or claim. Then the mechanism or evidence. Close with why it matters for someone running self-hosted or production infrastructure. No bullet lists, no preamble, no meta-commentary about the text or your process.'
      + (source === 'general web search' ? ' Begin the first sentence with exactly: Based on general web search (the original article could not be accessed): ' : '')
      + '>',
  ].join('\n');
}

const body = source === 'curator note only'
  ? '(page could not be retrieved)'
  : text;

const USER = [
  'TITLE: ' + (row.title || 'Untitled'),
  'URL: ' + (row.url || ''),
  'CURATOR NOTE: ' + (row.why || '(none)'),
  '',
  source === 'article' ? 'ARTICLE TEXT:'
    : source === 'general web search' ? 'WEB SEARCH RESULTS ABOUT THIS ARTICLE (the original page could not be retrieved):'
    : 'PAGE TEXT:',
  body,
].join('\n');

return {
  json: {
    row_id: row.id,
    title: row.title || 'Untitled',
    url: row.url || '',
    category: row.category || '',
    bucket: row.bucket || '',
    score: row.score != null ? row.score : '',
    source,
    chars: text.length,
    messages: [
      { role: 'system', content: SYS },
      { role: 'user', content: USER },
    ],
  },
};

// Build the sectioned body, a skimmable Headlines list, and the prompt for the
// 'At a glance' opener.
//
// Output contract: this node deliberately does NOT emit the final `brief`. It emits
// sections_md + glance_md + messages; 'Assemble brief' stitches the markdown once the
// overview text comes back from Ollama.
//
// Ollama /api/chat returns { message: { content } }; the old /v1 shape was
// { choices: [ { message: { content } } ] } - both are handled.
const results = $input.all();
const prepped = $('Prep item').all().map((x) => x.json);
const gate = $('Filter deals + dedupe').all().map((x) => x.json);
const today = new Date().toISOString().slice(0, 10);

function contentOf(r) {
  if (!r) return '';
  if (r.message && typeof r.message.content === 'string') return r.message.content;
  if (r.choices && r.choices[0] && r.choices[0].message) return String(r.choices[0].message.content || '');
  return '';
}
function strip(t) {
  return String(t || '').replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
}

const SECTION_ORDER = [
  ['AI & Top Tech', ['ai', 'news']],
  ['Business & Market Moves', ['business', 'career']],
  ['Deep Technical Reads', ['infra', 'storage', 'security']],
  ['Homelab & Misc', ['homelab', 'noise']],
];
function sectionTitle(bucket) {
  const b = String(bucket || '').toLowerCase();
  const hit = SECTION_ORDER.find(([, buckets]) => buckets.includes(b));
  return hit ? hit[0] : 'Homelab & Misc';
}
const EMOJI = { news: '📰', business: '💵', ai: '🤖', security: '🔒', infra: '⚙️', storage: '🗄️', homelab: '🏠', career: '🎯', noise: '·' };

const tally = { article: 0, 'general web search': 0, 'curator note only': 0 };
let ok = 0;
let failed = 0;
const items = [];

prepped.forEach((p, i) => {
  const r = results[i] ? results[i].json : {};
  let text = strip(contentOf(r));
  if (!text && r && r.error) text = `(summary failed: ${r.error.message || r.error})`;
  if (text && !text.startsWith('(summary failed')) ok += 1; else failed += 1;
  if (tally[p.source] !== undefined) tally[p.source] += 1;
  items.push({ ...p, summary: text || '(no summary returned)', section: sectionTitle(p.bucket) });
});

// Retire every row the gate considered, not just the ones that made the cut.
const gateIds = gate.length && Array.isArray(gate[0].eligible_ids) ? gate[0].eligible_ids : [];
const briefed_ids = gateIds.length
  ? gateIds
  : prepped.map((p) => p.row_id).filter((v) => v !== undefined && v !== null);

const availableBySection = {};
gate.forEach((g) => { if (g.section_title) availableBySection[g.section_title] = g.section_available; });

// Ordered item list, used for both the Headlines block and the overview prompt.
const ordered = [];
SECTION_ORDER.forEach(([title]) => {
  items.filter((it) => it.section === title)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0))
    .forEach((it) => ordered.push(it));
});

// Skimmable one-line-per-item list with links.
const glance = ordered.map((it) => `- ${EMOJI[String(it.bucket).toLowerCase()] || '•'} **[${it.score}]** [${String(it.title).replace(/[\[\]]/g, '')}](${it.url})`);

const body = [];
let n = 0;
SECTION_ORDER.forEach(([title]) => {
  const inSection = items.filter((it) => it.section === title)
    .sort((a, b) => Number(b.score || 0) - Number(a.score || 0));
  if (!inSection.length) return;
  const avail = availableBySection[title];
  const more = (avail && avail > inSection.length) ? ` · ${avail - inSection.length} more held back` : '';
  body.push(`# ${title}${more}`);
  body.push('');
  inSection.forEach((it) => {
    n += 1;
    body.push(`## ${n}. ${it.title}`);
    body.push(it.url);
    body.push(`*${it.bucket} · ${it.category} · score ${it.score}*`);
    body.push('');
    body.push(it.summary);
    body.push('');
  });
});

// Prompt for the 'At a glance' opener. Only the selected items are described, so the
// opener can never reference something that is not in the brief.
const overviewInput = ordered.map((it) => `[${it.bucket} ${it.score}] ${it.title}\n${String(it.summary).replace(/\s+/g, ' ').slice(0, 260)}`).join('\n\n');
const OSYS = [
  "You write the 'At a glance' opener for Deep's tech news brief. He reads it to decide what to click.",
  '',
  'Write 4 to 6 short lines of plain prose. Rules:',
  '- Lead with the single most important story of this batch.',
  '- Group related items into one line where they belong together.',
  '- Cover every theme present, at least in passing: AI, general tech, business/market, technical, homelab.',
  '- Name specific companies, products and numbers that appear in the items.',
  '- Use ONLY what is in the list. Never invent a story, a number or an outcome.',
  '- No preamble, no headings, no bullet markers, no closing summary. Just the lines.',
].join('\n');

return [{
  json: {
    sections_md: body.join('\n'),
    glance_md: glance.join('\n'),
    total_items: prepped.length,
    summarised: ok,
    failed,
    sources: tally,
    briefed_ids,
    generated: today,
    section_counts: availableBySection,
    messages: [
      { role: 'system', content: OSYS },
      { role: 'user', content: `Items in today's brief (${ordered.length}):\n\n${overviewInput}` },
    ],
  },
}];

// runOnceForAllItems: the brief's editorial gate. Runs before anything is fetched
// or summarised, so whatever it drops costs nothing downstream.
//
// 1. Drops retail/deal rows (belt and braces - the curator no longer scores them).
// 2. Collapses identical URLs (same article via a digest feed and its source feed).
// 3. Collapses NEAR-duplicates by title (2026-09-27). Exact-URL dedupe missed the
//    common case: one story syndicated across Bloomberg, CNBC and The Verge with
//    slightly different headlines. Titles are normalised, stopwords dropped, and
//    compared by Jaccard overlap; >= 0.6 counts as the same story and the higher
//    score wins.
// 4. Assigns a SECTION, RESERVES slots per bucket, then caps the section.
// 5. Emits eligible_ids so Mark briefed retires everything considered - including
//    the duplicates and the capped-out rows - so the pool cannot grow without bound.
const COMMERCE = /deal|slickdeal|coupon|bargain|woot|frugal|shopping|clearance/i;

// key, title, cap, buckets, reserve (minimum slots guaranteed per bucket)
const SECTIONS = [
  ['top', 'AI & Top Tech', 6, ['ai', 'news'], { news: 3, ai: 3 }],
  ['money', 'Business & Market Moves', 4, ['business', 'career'], { business: 3 }],
  ['deep', 'Deep Technical Reads', 5, ['infra', 'storage', 'security'], { security: 2 }],
  ['lab', 'Homelab & Misc', 3, ['homelab', 'noise'], {}],
];
const sectionOf = (bucket) => {
  const b = String(bucket || '').toLowerCase();
  const hit = SECTIONS.find(([, , , buckets]) => buckets.includes(b));
  return hit ? hit[0] : 'lab';
};

function urlKey(u) {
  return String(u || '').trim().replace(/[#?].*$/, '').replace(/\/+$/, '').toLowerCase();
}
const byScoreThenRecency = (a, b) => (Number(b.json.score || 0) - Number(a.json.score || 0))
  || (new Date(b.json.createdAt || 0) - new Date(a.json.createdAt || 0));

// --- near-duplicate helpers -------------------------------------------------
const STOP = new Set(['the', 'and', 'for', 'with', 'from', 'into', 'over', 'amid', 'after', 'says', 'say', 'said', 'new', 'now', 'its', 'has', 'have', 'will', 'that', 'this', 'are', 'was', 'were', 'but', 'not', 'you', 'your', 'how', 'why', 'what', 'about', 'more', 'than', 'out', 'off', 'per', 'via', 'amp']);
function normTitle(t) {
  return String(t || '').toLowerCase().replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function titleTokens(t) {
  return new Set(normTitle(t).split(' ').filter((w) => w.length > 2 && !STOP.has(w)));
}
function jaccard(a, b) {
  if (!a.size || !b.size) return 0;
  let inter = 0;
  a.forEach((w) => { if (b.has(w)) inter += 1; });
  return inter / (a.size + b.size - inter);
}
const SIMILAR_AT = 0.6;

const kept = new Map();
let droppedCommerce = 0;
let droppedDuplicate = 0;

$input.all().forEach((item, idx) => {
  const r = item.json || {};
  if (COMMERCE.test(String(r.category || '')) || COMMERCE.test(String(r.feed || ''))) {
    droppedCommerce += 1;
    return;
  }
  const key = urlKey(r.url) || `row-${r.id}`;
  const prev = kept.get(key);
  if (prev && Number(prev.json.score || 0) >= Number(r.score || 0)) {
    droppedDuplicate += 1;
    return;
  }
  if (prev) droppedDuplicate += 1;
  kept.set(key, { json: r, pairedItem: item.pairedItem !== undefined ? item.pairedItem : { item: idx } });
});

// Everything considered this run gets retired, duplicates included.
const eligibleIds = [...kept.values()].map((it) => it.json.id).filter((v) => v !== undefined && v !== null);

// Highest score first, so the survivor of a duplicate group is the best-scored one.
const unique = [];
let droppedSimilar = 0;
const similarLog = [];
[...kept.values()].sort(byScoreThenRecency).forEach((it) => {
  const tok = titleTokens(it.json.title);
  const norm = normTitle(it.json.title);
  const clash = unique.find((u) => u.norm === norm || jaccard(u.tok, tok) >= SIMILAR_AT);
  if (clash) {
    droppedSimilar += 1;
    if (similarLog.length < 5) similarLog.push(String(it.json.title).slice(0, 48) + ' ~ ' + String(clash.json.title).slice(0, 48));
    return;
  }
  unique.push({ ...it, tok, norm });
});

const out = [];
const counts = {};
SECTIONS.forEach(([key, title, cap, , reserve]) => {
  const pool = unique.filter((it) => sectionOf(it.json.bucket) === key).sort(byScoreThenRecency);
  const picked = [];
  const taken = new Set();

  // Reserved slots first, so a loud bucket cannot starve a quiet one.
  Object.entries(reserve || {}).forEach(([bucket, n]) => {
    pool.filter((it) => String(it.json.bucket || '').toLowerCase() === bucket)
      .slice(0, n)
      .forEach((it) => {
        if (picked.length < cap && !taken.has(it.json.id)) { picked.push(it); taken.add(it.json.id); }
      });
  });
  pool.forEach((it) => {
    if (picked.length < cap && !taken.has(it.json.id)) { picked.push(it); taken.add(it.json.id); }
  });

  picked.sort(byScoreThenRecency);
  counts[title] = { picked: picked.length, available: pool.length };
  picked.forEach((it) => {
    out.push({
      json: { ...it.json, section_key: key, section_title: title, section_available: pool.length, eligible_ids: eligibleIds },
      pairedItem: it.pairedItem,
    });
  });
});

console.log('brief gate: ' + out.length + ' kept of ' + kept.size + ' eligible; dropped ' + droppedCommerce + ' commerce, ' + droppedDuplicate + ' same-url, ' + droppedSimilar + ' near-duplicate; ' + JSON.stringify(counts));
if (similarLog.length) console.log('near-duplicates merged: ' + similarLog.join(' | '));
return out;

// Final markdown: 'At a glance' opener, then a skimmable linked Headlines list,
// then the full sectioned summaries. The opener is generated by Ollama: overview;
// if that call failed we simply omit it rather than blocking the brief.
const c = $('Collect').first().json;
const resp = $json || {};

function contentOf(r) {
  if (r && r.message && typeof r.message.content === 'string') return r.message.content;
  if (r && r.choices && r.choices[0] && r.choices[0].message) return String(r.choices[0].message.content || '');
  return '';
}
const overview = String(contentOf(resp))
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(/^\s*[-*•]\s*/gm, '')
  .trim();

const partOfDay = new Date().getHours() < 12 ? 'Morning' : 'Evening';
const sectionsPresent = Object.keys(c.section_counts || {}).length;

const out = [
  `# Miniflux Curator Brief - ${c.generated} (${partOfDay})`,
  '',
  `${c.total_items} item(s) across ${sectionsPresent} section(s), selected from ${(c.briefed_ids || []).length} scored candidate(s). Summaries by qwen3.6:35b-a3b.`,
  `${c.summarised} summarised, ${c.failed} failed · sources: ${c.sources.article} article, ${c.sources['general web search']} web search, ${c.sources['curator note only']} curator-note-only`,
  '',
];

if (overview) {
  out.push('## At a glance', '', overview, '');
} else {
  out.push('## At a glance', '', '_(overview unavailable for this run)_', '');
}

out.push('## Headlines', '', c.glance_md, '', '---', '');
out.push(c.sections_md);

const brief = out.join('\n');
return [{
  json: {
    brief,
    overview: overview || '',
    total_items: c.total_items,
    summarised: c.summarised,
    failed: c.failed,
    sources: c.sources,
    briefed_ids: c.briefed_ids,
    generated: c.generated,
    part_of_day: partOfDay,
  },
}];
